                                { "@type": "Question", "name": "How do I avoid the crowds on Koh Larn?", "acceptedAnswer": { "@type": "Answer", "text": "Take the 7:00 AM ferry for two to three hours of near-empty beaches before tour boats arrive around 10:30. Avoid weekends and Thai holidays, or stay overnight — the island empties after the last ferry around 6 PM." } },
                                { "@type": "Question", "name": "Is the snorkelling good at Koh Larn?", "acceptedAnswer": { "@type": "Answer", "text": "Not especially — the reefs have been substantially damaged by decades of boat traffic and anchoring despite the Coral Island marketing. The outer islands are clearer, and the Andaman coast is far better." } }
